INSERT INTO _sting_faction_guard VALUES('client_factions',((SELECT COUNT(*) FROM faction_list WHERE base=0 AND((id=1123 AND name='Drones of Stonehive')OR(id=1124 AND name='Legion of Stonehive')OR(id=1129 AND name='Circle of the Crystalwing')))=3));
INSERT INTO _sting_faction_guard VALUES('reachable_gate',(EXISTS(SELECT 1 FROM faction_base_data WHERE client_faction_id=1124 AND min<= -1500 AND max=0)));
INSERT INTO _sting_faction_guard VALUES('npc_faction',(NOT EXISTS(SELECT 1 FROM npc_faction WHERE (id=396942) AND NOT((`id` <=> 396942 AND `name` <=> 'May2013 Stonehive labelled kill defaults' AND `primaryfaction` <=> 0 AND `ignore_primary_assist` <=> 0)))));
INSERT INTO npc_faction(`id`,`name`,`primaryfaction`,`ignore_primary_assist`)VALUES (396942,'May2013 Stonehive labelled kill defaults',0,0) ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`primaryfaction`=VALUES(`primaryfaction`),`ignore_primary_assist`=VALUES(`ignore_primary_assist`);
INSERT INTO _sting_faction_guard VALUES('npc_faction_entries',(NOT EXISTS(SELECT 1 FROM npc_faction_entries WHERE (npc_faction_id=396942) AND NOT((`npc_faction_id` <=> 396942 AND `faction_id` <=> 1123 AND `value` <=> -1 AND `npc_value` <=> 0 AND `temp` <=> 0) OR (`npc_faction_id` <=> 396942 AND `faction_id` <=> 1124 AND `value` <=> -1 AND `npc_value` <=> 0 AND `temp` <=> 0) OR (`npc_faction_id` <=> 396942 AND `faction_id` <=> 1129 AND `value` <=> 1 AND `npc_value` <=> 0 AND `temp` <=> 0)))));
INSERT INTO npc_faction_entries(`npc_faction_id`,`faction_id`,`value`,`npc_value`,`temp`)VALUES (396942,1123,-1,0,0),(396942,1124,-1,0,0),(396942,1129,1,0,0) ON DUPLICATE KEY UPDATE `value`=VALUES(`value`),`npc_value`=VALUES(`npc_value`),`temp`=VALUES(`temp`);
